    @Test
    public void testEqualsWithNullSnapshotInfo() {
        // Create two Version instances with null snapshotInfo
        Version v1 = new Version(1, 0, 0, null, "group", "artifact");
        Version v2 = new Version(1, 0, 0, null, "group", "artifact");

        // Should not throw NPE and should be equal
        assertEquals(v1, v2);
        assertTrue(v1.equals(v2));
    }

