        Version v2 = new Version(1, 0, 0, "SNAPSHOT", "group", "artifact");

        // Should not throw NPE and should not be equal
        assertFalse(v1.equals(v2));
        assertFalse(v2.equals(v1));
    }

    @Test
    public void testEqualsWithBothNonNullSnapshotInfo() {
        // Both with non-null snapshotInfo
        Version v1 = new Version(1, 0, 0, "SNAPSHOT", "group", "artifact");
        Version v2 = new Version(1, 0, 0, "SNAPSHOT", "group", "artifact");
        Version v3 = new Version(1, 0, 0, "RELEASE", "group", "artifact");

        // Equal snapshotInfo should be equal
        assertEquals(v1, v2);
        assertTrue(v1.equals(v2));

        // Different snapshotInfo should not be equal
        assertFalse(v1.equals(v3));
    }

    @Test
    public void testHashCodeWithNullSnapshotInfo() {
        // Should not throw NPE when computing hashCode with null snapshotInfo
        Version v1 = new Version(1, 0, 0, null, "group", "artifact");

        // Should not throw NPE
        int hashCode = v1.hashCode();
        // Verify hashCode is consistent
        assertEquals(hashCode, v1.hashCode());
    }

    @Test
    public void testHashCodeWithNonNullSnapshotInfo() {
        // Should work correctly with non-null snapshotInfo
        Version v1 = new Version(1, 0, 0, "SNAPSHOT", "group", "artifact");

        // Should not throw NPE
        int hashCode = v1.hashCode();
        // Verify hashCode is consistent
        assertEquals(hashCode, v1.hashCode());
    }

    @Test
    public void testUnknownVersionEquals() {
        // UNKNOWN_VERSION has null snapshotInfo
        Version unknown1 = Version.unknownVersion();
        Version unknown2 = Version.unknownVersion();

        // Should not throw NPE
