        // Create version with null snapshotInfo
        Version v1 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");
        Version v2 = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");

        // Should not throw NPE
        int hash1 = v1.hashCode();
        int hash2 = v2.hashCode();

        // Equal objects should have equal hash codes
        assertEquals(hash1, hash2);
    }

    @Test
    public void testHashCodeWithNonNullSnapshotInfo() {
