        // Should not throw NPE
        int hash = unknown.hashCode();

        // Hash code should be consistent
        assertEquals(hash, unknown.hashCode());
    }

    @Test
    public void testEqualsReflexivity() {
        Version v = new Version(2, 16, 0, null, "com.fasterxml.jackson.core", "jackson-core");

        // Should be equal to itself
