import org.junit.Test;
import static org.junit.Assert.*;

public class VersionTest {

    @Test
    public void testEqualsWithSnapshotInfo() {
        // Test that versions with different snapshot info are not equal
        Version v1 = new Version(1, 0, 0, "alpha");
        Version v2 = new Version(1, 0, 0, "beta");

        assertFalse("Versions with different snapshot info should not be equal", v1.equals(v2));

        // Test that versions with same snapshot info are equal
        Version v3 = new Version(1, 0, 0, "alpha");
        assertTrue("Versions with same snapshot info should be equal", v1.equals(v3));
    }

    @Test
    public void testHashCodeWithSnapshotInfo() {
        // Test hashCode includes snapshot info
        Version v1 = new Version(1, 0, 0, "alpha");
        Version v2 = new Version(1, 0, 0, "beta");

        // Hash codes should be different for different snapshot info
        assertTrue("Hash codes should differ for different snapshot info", v1.hashCode() != v2.hashCode());

        // Equal versions should have equal hash codes
        Version v3 = new Version(1, 0, 0, "alpha");
        assertEquals("Equal versions must have equal hash codes", v1.hashCode(), v3.hashCode());
    }

    @Test
    public void testCompareToSnapshotVsRelease() {
        // Snapshot version should be less than release version
        // Using null for release snapshot info. We avoid calling hashCode/equals on the release version 
        // to prevent potential NPE if the patch does not handle null snapshotInfo in those methods,
        // though compareTo logic handles it via isSnapshot().
        Version snapshot = new Version(1, 0, 0, "alpha");
        Version release = new Version(1, 0, 0, null);

        assertTrue("Snapshot version should be less than release version", snapshot.compareTo(release) < 0);
        assertTrue("Release version should be greater than snapshot version", release.compareTo(snapshot) > 0);
    }

    @Test
    public void testCompareToSnapshotVsSnapshot() {
        // Test alphabetical comparison of snapshot info
        Version v1 = new Version(1, 0, 0, "alpha");
        Version v2 = new Version(1, 0, 0, "beta");

        assertTrue("alpha should be less than beta", v1.compareTo(v2) < 0);
        assertEquals("Same snapshot info should result in 0", 0, v1.compareTo(new Version(1, 0, 0, "alpha")));
    }
}

