package com.fasterxml.jackson.core;

import static org.junit.Assert.*;
import org.junit.Test;

public class VersionTest {

    @Test
    public void testEqualsAndHashCodeWithSnapshotInfo() {
        Version v1 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v2 = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version v3 = new Version(1, 0, 0, "beta", "com.example", "artifact");
        Version v4 = new Version(1, 0, 0, "", "com.example", "artifact");

        // Equal versions with same snapshot info should be equal and have same hash code
        assertEquals(v1, v2);
        assertEquals(v1.hashCode(), v2.hashCode());

        // Different snapshot info should not be equal
        assertNotEquals(v1, v3);
        assertNotEquals(v1, v4);
    }

    @Test
    public void testCompareToSnapshotPrecedence() {
        // Reproduction case from requirements:
        // Previously, this would return 0 (equal), which is incorrect.
        Version vAlpha = new Version(1, 0, 0, "alpha", "com.example", "artifact");
        Version vBeta = new Version(1, 0, 0, "beta", "com.example", "artifact");
        Version vRelease = new Version(1, 0, 0, "", "com.example", "artifact");

        // Snapshot vs Snapshot (lexicographical)
        assertTrue("alpha should be less than beta", vAlpha.compareTo(vBeta) < 0);
        assertTrue("beta should be greater than alpha", vBeta.compareTo(vAlpha) > 0);
        assertEquals("alpha should be equal to alpha", 0, vAlpha.compareTo(vAlpha));

        // Snapshot vs Non-Snapshot (Release)
        // Assuming empty string "" results in isSnapshot() == false
        assertTrue("Snapshot should be less than Release", vAlpha.compareTo(vRelease) < 0);
        assertTrue("Release should be greater than Snapshot", vRelease.compareTo(vAlpha) > 0);

        // Release vs Release
        assertEquals("Release should be equal to Release", 0, vRelease.compareTo(vRelease));
    }
}

