import org.junit.Test;

import static org.junit.Assert.*;

public class NonBlockingJsonParserCanonicalizationTest {

    @Test
    public void testNonBlockingParserRespectsCanonicalizeFieldNamesDisabled() throws Exception {
        // Create factory with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = JsonFactory.builder()
            .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
            .build();

        // Create non-blocking parser
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();

        // Check that the symbol table is not canonicalizing
        ByteQuadsCanonicalizer symbols = parser.symbolTableForTests();
        assertNotNull("Symbol table should not be null", symbols);
        assertFalse("Symbol table should not be canonicalizing when feature is disabled", 
                    symbols.isCanonicalizing());

        // Parse some JSON with field names to ensure it works correctly
        String json = "{\"field1\":\"value1\",\"field2\":\"value2\"}";
        byte[] data = json.getBytes("UTF-8");

        parser.feedInput(data, 0, data.length);
        parser.endOfInput();

        // Verify field names are parsed correctly
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("field1", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value1", parser.getText());

        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("field2", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value2", parser.getText());

        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());

        parser.close();
    }

