package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import org.junit.Test;
import java.io.*;

import static org.junit.Assert.*;

public class NextFieldNameTrailingCommaTest {

    @Test
    public void testNextFieldNameWithTrailingCommaInObject() throws IOException {
        JsonFactory factory = new JsonFactory();
        factory = factory.configure(JsonParser.Feature.ALLOW_TRAILING_COMMA, true);

        String json = "{\"field1\": \"value1\",}";
        JsonParser parser = factory.createParser(json);

        // Start parsing
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Get first field name
        String fieldName = parser.nextFieldName();
        assertEquals("field1", fieldName);

        // Get the value
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value1", parser.getText());

        // Next field name should be null (end of object) - this is where the bug was
        fieldName = parser.nextFieldName();
        assertNull(fieldName);

        // Should be at END_OBJECT
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        parser.close();
    }

    @Test
    public void testNextFieldNameWithTrailingCommaInNestedObject() throws IOException {
        JsonFactory factory = new JsonFactory();
        factory = factory.configure(JsonParser.Feature.ALLOW_TRAILING_COMMA, true);

        String json = "{\"outer\": {\"inner\": \"value\",},}";
        JsonParser parser = factory.createParser(json);

        // Start parsing
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Get outer field name
        String fieldName = parser.nextFieldName();
        assertEquals("outer", fieldName);

        // Get the nested object
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Get inner field name
        fieldName = parser.nextFieldName();
        assertEquals("inner", fieldName);

        // Get the value
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value", parser.getText());

        // Next field name should be null (end of inner object)
        fieldName = parser.nextFieldName();
        assertNull(fieldName);

        // Should be at END_OBJECT (inner)
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        // Next field name should be null (end of outer object)
        fieldName = parser.nextFieldName();
        assertNull(fieldName);

        // Should be at END_OBJECT (outer)
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        parser.close();
    }

    @Test
    public void testNextFieldNameWithTrailingCommaInArray() throws IOException {
        JsonFactory factory = new JsonFactory();
        factory = factory.configure(JsonParser.Feature.ALLOW_TRAILING_COMMA, true);

        String json = "[{\"field1\": \"value1\"},]";
        JsonParser parser = factory.createParser(json);

        // Start parsing
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());

        // Get first object
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Get field name
        String fieldName = parser.nextFieldName();
        assertEquals("field1", fieldName);

        // Get the value
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value1", parser.getText());

        // Next field name should be null (end of object)
        fieldName = parser.nextFieldName();
        assertNull(fieldName);

        // Should be at END_OBJECT
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        // Next token should be END_ARRAY
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());

        parser.close();
    }

    @Test
    public void testNextFieldNameWithoutTrailingCommaFeature() throws IOException {
        JsonFactory factory = new JsonFactory();
        // Don't enable ALLOW_TRAILING_COMMA

        String json = "{\"field1\": \"value1\",}";
        JsonParser parser = factory.createParser(json);

        // Start parsing
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Get first field name
        String fieldName = parser.nextFieldName();
        assertEquals("field1", fieldName);

        // Get the value
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value1", parser.getText());

        // Next field name should throw exception without trailing comma feature
        try {
            fieldName = parser.nextFieldName();
            fail("Expected JsonParseException");
        } catch (JsonParseException e) {
            // Expected
        }

        parser.close();
    }

    @Test
    public void testNextFieldNameWithMultipleTrailingCommas() throws IOException {
        JsonFactory factory = new JsonFactory();
        factory = factory.configure(JsonParser.Feature.ALLOW_TRAILING_COMMA, true);

        String json = "{\"a\": 1, \"b\": 2,}";
        JsonParser parser = factory.createParser(json);

        // Start parsing
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Get first field name
        String fieldName = parser.nextFieldName();
        assertEquals("a", fieldName);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());

        // Get second field name
        fieldName = parser.nextFieldName();
        assertEquals("b", fieldName);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(2, parser.getIntValue());

        // Next field name should be null (end of object with trailing comma)
        fieldName = parser.nextFieldName();
        assertNull(fieldName);

        // Should be at END_OBJECT
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        parser.close();
    }
}

