package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import org.junit.Test;

import java.lang.reflect.Field;

import static org.junit.Assert.*;

public class JsonFactoryStreamReadConstraintsTest {

    @Test
    public void testSetStreamReadConstraintsUpdatesRootCharSymbolsWhenMaxNameLengthChanges() throws Exception {
        // Create a JsonFactory instance
        JsonFactory factory = new JsonFactory();

        // Get the initial _rootCharSymbols reference using reflection
        Field rootCharSymbolsField = JsonFactory.class.getDeclaredField("_rootCharSymbols");
        rootCharSymbolsField.setAccessible(true);
        CharsToNameCanonicalizer initialRootCharSymbols = (CharsToNameCanonicalizer) rootCharSymbolsField.get(factory);

        // Store the initial maxNameLength
        int initialMaxNameLength = factory.streamReadConstraints().getMaxNameLength();

        // Set new stream read constraints with different maxNameLength
        int newMaxNameLength = initialMaxNameLength + 1000;
        StreamReadConstraints newConstraints = StreamReadConstraints.builder()
            .maxNameLength(newMaxNameLength)
            .build();
        factory.setStreamReadConstraints(newConstraints);

        // Get the updated _rootCharSymbols reference
        CharsToNameCanonicalizer updatedRootCharSymbols = (CharsToNameCanonicalizer) rootCharSymbolsField.get(factory);

        // Verify that _rootCharSymbols was recreated (different reference)
        assertNotSame("Root char symbols should be recreated when maxNameLength changes", 
            initialRootCharSymbols, updatedRootCharSymbols);

        // Verify the new constraints are applied
        assertEquals("New maxNameLength should be applied", newMaxNameLength, 
            factory.streamReadConstraints().getMaxNameLength());
    }

    @Test
    public void testSetStreamReadConstraintsDoesNotUpdateRootCharSymbolsWhenMaxNameLengthUnchanged() throws Exception {
        // Create a JsonFactory instance
        JsonFactory factory = new JsonFactory();

        // Get the initial _rootCharSymbols reference using reflection
        Field rootCharSymbolsField = JsonFactory.class.getDeclaredField("_rootCharSymbols");
        rootCharSymbolsField.setAccessible(true);
        CharsToNameCanonicalizer initialRootCharSymbols = (CharsToNameCanonicalizer) rootCharSymbolsField.get(factory);

        // Get the current maxNameLength
