        // Set new stream read constraints with SAME maxNameLength
        StreamReadConstraints newConstraints = StreamReadConstraints.builder()
            .maxNameLength(currentMaxNameLength)
            .build();
        factory.setStreamReadConstraints(newConstraints);

        // Get the updated _rootCharSymbols reference
        CharsToNameCanonicalizer updatedRootCharSymbols = (CharsToNameCanonicalizer) rootCharSymbolsField.get(factory);

        // Verify that _rootCharSymbols was NOT recreated (same reference)
        assertSame("Root char symbols should NOT be recreated when maxNameLength is unchanged", 
            initialRootCharSymbols, updatedRootCharSymbols);
    }

    @Test
    public void testSetStreamReadConstraintsReturnsThisForChaining() {
        // Create a JsonFactory instance
        JsonFactory factory = new JsonFactory();

        // Set new stream read constraints
        StreamReadConstraints newConstraints = StreamReadConstraints.builder()
            .maxNameLength(100_000)
            .build();

        // Verify method returns this for chaining
        JsonFactory returnedFactory = factory.setStreamReadConstraints(newConstraints);
        assertSame("setStreamReadConstraints should return this", factory, returnedFactory);
    }

    @Test
    public void testSetStreamReadConstraintsWithNullThrowsException() {
        // Create a JsonFactory instance
        JsonFactory factory = new JsonFactory();

        // Verify that setting null constraints throws NullPointerException
