    public void testSetStreamReadConstraintsMultipleChanges() throws Exception {
        // Create a JsonFactory instance
        JsonFactory factory = new JsonFactory();

        // Get the initial _rootCharSymbols reference using reflection
        Field rootCharSymbolsField = JsonFactory.class.getDeclaredField("_rootCharSymbols");
        rootCharSymbolsField.setAccessible(true);

        CharsToNameCanonicalizer initialRootCharSymbols = (CharsToNameCanonicalizer) rootCharSymbolsField.get(factory);

        // First change - different maxNameLength
        StreamReadConstraints constraints1 = StreamReadConstraints.builder()
            .maxNameLength(100_000)
            .build();
        factory.setStreamReadConstraints(constraints1);
        CharsToNameCanonicalizer afterFirstChange = (CharsToNameCanonicalizer) rootCharSymbolsField.get(factory);
        assertNotSame("Root char symbols should be recreated on first change", 
            initialRootCharSymbols, afterFirstChange);

        // Second change - same maxNameLength
        StreamReadConstraints constraints2 = StreamReadConstraints.builder()
            .maxNameLength(100_000)
            .build();
        factory.setStreamReadConstraints(constraints2);
        CharsToNameCanonicalizer afterSecondChange = (CharsToNameCanonicalizer) rootCharSymbolsField.get(factory);
        assertSame("Root char symbols should NOT be recreated when maxNameLength is unchanged", 
