package com.fasterxml.jackson.core;

import org.junit.Test;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.JsonParser.NumberTypeFP;
import com.fasterxml.jackson.core.util.JsonParserDelegate;

import static org.junit.Assert.*;

/**
 * Unit tests for JsonParser.getNumberTypeFP() method and NumberTypeFP enum.
 * Tests cover the new floating-point number type detection API added in version 2.17.
 */
public class JsonParserNumberTypeFPTest {

    @Test
    public void testGetNumberTypeFPDefaultImplementationReturnsUnknown() throws Exception {
        // Test that default implementation returns UNKNOWN for JSON format
        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser("1.5")) {
            parser.nextToken(); // Move to VALUE_NUMBER_FLOAT
            NumberTypeFP typeFP = parser.getNumberTypeFP();

            // Default implementation should return UNKNOWN for textual formats like JSON
            assertEquals("Default getNumberTypeFP() should return UNKNOWN", 
                         NumberTypeFP.UNKNOWN, typeFP);
            assertNotNull("getNumberTypeFP() should never return null", typeFP);
        }
    }

    @Test
    public void testGetNumberTypeFPWithIntegerToken() throws Exception {
        // Test with integer token - should still return UNKNOWN
        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser("42")) {
            parser.nextToken(); // Move to VALUE_NUMBER_INT
            NumberTypeFP typeFP = parser.getNumberTypeFP();

            // For integer tokens, should return UNKNOWN (method is primarily for FP types)
            assertEquals(NumberTypeFP.UNKNOWN, typeFP);
            assertNotNull(typeFP);
        }
    }

    @Test
    public void testGetNumberTypeFPWithDecimalNumber() throws Exception {
        // Test with various decimal numbers
        JsonFactory factory = new JsonFactory();
        String[] decimalValues = {"0.1", "3.14159", "1.0", "0.25", "100.001"};

        for (String value : decimalValues) {
            try (JsonParser parser = factory.createParser(value)) {
                parser.nextToken();
                assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());

                NumberTypeFP typeFP = parser.getNumberTypeFP();
                assertNotNull("getNumberTypeFP() should not return null for " + value, typeFP);
                assertEquals(NumberTypeFP.UNKNOWN, typeFP);
            }
        }
    }

    @Test
    public void testGetNumberTypeFPWithJsonParserDelegate() throws Exception {
        // Test that JsonParserDelegate properly delegates the call
        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser("2.71828")) {
            parser.nextToken();

            // Wrap in delegate
            JsonParserDelegate delegate = new JsonParserDelegate(parser);
            NumberTypeFP delegateTypeFP = delegate.getNumberTypeFP();
            NumberTypeFP originalTypeFP = parser.getNumberTypeFP();

            // Delegate should return same value as underlying parser
            assertEquals("Delegate should return same value as underlying parser", 
                         originalTypeFP, delegateTypeFP);
            assertNotNull(delegateTypeFP);
        }
    }

    @Test
    public void testGetNumberTypeFPWithNonNumericToken() throws Exception {
        // Test with non-numeric tokens
        JsonFactory factory = new JsonFactory();
        String[] nonNumericValues = {"\"text\"", "true", "false", "null"};

        for (String value : nonNumericValues) {
            try (JsonParser parser = factory.createParser(value)) {
                parser.nextToken();

                NumberTypeFP typeFP = parser.getNumberTypeFP();
                assertNotNull("getNumberTypeFP() should not return null for " + value, typeFP);
                assertEquals(NumberTypeFP.UNKNOWN, typeFP);
            }
        }
    }

    @Test
    public void testGetNumberTypeFPBeforeFirstToken() throws Exception {
        // Test calling before nextToken() is called
        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser("1.5")) {
            // Don't call nextToken() - parser is before first token
            NumberTypeFP typeFP = parser.getNumberTypeFP();

            assertNotNull("getNumberTypeFP() should not return null before first token", typeFP);
            assertEquals(NumberTypeFP.UNKNOWN, typeFP);
        }
    }

    @Test
    public void testGetNumberTypeFPAfterParserClosed() throws Exception {
        // Test behavior after parser is closed
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser("1.5");
        parser.nextToken();
        parser.close();

        // Should still return UNKNOWN (not null) even after close
        NumberTypeFP typeFP = parser.getNumberTypeFP();
        assertNotNull("getNumberTypeFP() should not return null after close", typeFP);
    }

    @Test
    public void testNumberTypeFPEnumValuesExist() {
        // Verify all NumberTypeFP enum constants exist
        assertNotNull("FLOAT16 enum value should exist", NumberTypeFP.FLOAT16);
        assertNotNull("FLOAT32 enum value should exist", NumberTypeFP.FLOAT32);
        assertNotNull("DOUBLE64 enum value should exist", NumberTypeFP.DOUBLE64);
        assertNotNull("BIG_DECIMAL enum value should exist", NumberTypeFP.BIG_DECIMAL);
        assertNotNull("UNKNOWN enum value should exist", NumberTypeFP.UNKNOWN);
    }

    @Test
    public void testNumberTypeFPEnumHasCorrectNumberOfValues() {
        // Verify the enum has exactly 5 values
        NumberTypeFP[] values = NumberTypeFP.values();
        assertEquals("NumberTypeFP should have exactly 5 enum values", 5, values.length);
    }

    @Test
    public void testNumberTypeFPEnumValueOf() {
        // Test that valueOf works correctly for all enum constants
        assertEquals(NumberTypeFP.FLOAT16, NumberTypeFP.valueOf("FLOAT16"));
        assertEquals(NumberTypeFP.FLOAT32, NumberTypeFP.valueOf("FLOAT32"));
        assertEquals(NumberTypeFP.DOUBLE64, NumberTypeFP.valueOf("DOUBLE64"));
        assertEquals(NumberTypeFP.BIG_DECIMAL, NumberTypeFP.valueOf("BIG_DECIMAL"));
        assertEquals(NumberTypeFP.UNKNOWN, NumberTypeFP.valueOf("UNKNOWN"));
    }

    @Test
    public void testGetNumberTypeFPWithNegativeNumbers() throws Exception {
        // Test with negative floating-point numbers
        JsonFactory factory = new JsonFactory();
        String[] negativeValues = {"-1.5", "-0.001", "-100.5"};

        for (String value : negativeValues) {
            try (JsonParser parser = factory.createParser(value)) {
                parser.nextToken();
                assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());

                NumberTypeFP typeFP = parser.getNumberTypeFP();
                assertNotNull("getNumberTypeFP() should not return null for " + value, typeFP);
                assertEquals(NumberTypeFP.UNKNOWN, typeFP);
            }
        }
    }

    @Test
    public void testGetNumberTypeFPWithScientificNotation() throws Exception {
        // Test with scientific notation numbers
        JsonFactory factory = new JsonFactory();
        String[] scientificValues = {"1.5e10", "2.5E-5", "3.0e+2"};

        for (String value : scientificValues) {
            try (JsonParser parser = factory.createParser(value)) {
                parser.nextToken();
                assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());

                NumberTypeFP typeFP = parser.getNumberTypeFP();
                assertNotNull("getNumberTypeFP() should not return null for " + value, typeFP);
                assertEquals(NumberTypeFP.UNKNOWN, typeFP);
            }
        }
    }

    @Test
    public void testGetNumberTypeAndNumberTypeFPConsistency() throws Exception {
        // Test that getNumberType() and getNumberTypeFP() work together
        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser("1.5")) {
            parser.nextToken();

            NumberType numberType = parser.getNumberType();
            NumberTypeFP numberTypeFP = parser.getNumberTypeFP();

            // For JSON, getNumberType() returns DOUBLE for floats
            // getNumberTypeFP() returns UNKNOWN (more precise info not available)
            assertNotNull(numberType);
            assertNotNull(numberTypeFP);
            assertEquals(NumberTypeFP.UNKNOWN, numberTypeFP);
        }
    }

    @Test
    public void testGetNumberTypeFPWithZero() throws Exception {
        // Test with zero values
        JsonFactory factory = new JsonFactory();
        String[] zeroValues = {"0.0", "0", "-0.0"};

        for (String value : zeroValues) {
            try (JsonParser parser = factory.createParser(value)) {
                parser.nextToken();

                NumberTypeFP typeFP = parser.getNumberTypeFP();
                assertNotNull("getNumberTypeFP() should not return null for " + value, typeFP);
            }
        }
    }

    @Test
    public void testGetNumberTypeFPWithLargeDecimal() throws Exception {
        // Test with large decimal number
        JsonFactory factory = new JsonFactory();
        String largeDecimal = "123456789.123456789";

        try (JsonParser parser = factory.createParser(largeDecimal)) {
            parser.nextToken();
            assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());

            NumberTypeFP typeFP = parser.getNumberTypeFP();
            assertNotNull("getNumberTypeFP() should not return null for large decimal", typeFP);
            assertEquals(NumberTypeFP.UNKNOWN, typeFP);
        }
    }
}

