package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for JsonPointer.append(JsonPointer) method.
 * Specifically tests issue #1168 where append(JsonPointer.tail()) 
 * incorrectly included the original pointer's segments.
 */
public class JsonPointerAppendTest {

    /**
     * Test for issue #1168: JsonPointer.append(JsonPointer.tail()) includes the original pointer
     * 
     * This test verifies that when appending a tail pointer to another pointer,
     * the result correctly uses only the tail's subpath, not the original full path.
     */
    @Test
    public void testAppendTailPointer() {
        // Create original pointer: /a1/b/c
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail pointer: should represent /b/c
        JsonPointer tailPointer = original.tail();

        // Create another pointer: /a2
        JsonPointer other = JsonPointer.compile("/a2");

        // Append tail to other: should result in /a2/b/c
        JsonPointer concatenated = other.append(tailPointer);

        // Verify the result is correct
        assertEquals("/a2/b/c", concatenated.toString());

        // Also verify it equals a directly compiled pointer
        JsonPointer expected = JsonPointer.compile("/a2/b/c");
        assertEquals(expected, concatenated);
    }

    /**
     * Additional test: Verify tail() returns correct pointer before append
     */
    @Test
    public void testTailPointerRepresentation() {
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail();

        // Tail should represent /b/c
        assertEquals("/b/c", tailPointer.toString());

        // Verify tail is not the same as original
        assertNotEquals(original, tailPointer);
    }

    /**
     * Test append with empty pointer cases
     */
    @Test
    public void testAppendWithEmptyPointer() {
        JsonPointer pointer = JsonPointer.compile("/a/b");
        JsonPointer empty = JsonPointer.empty();

        // Appending empty should return the original
        assertSame(pointer, pointer.append(empty));

        // Prepending empty should return the other pointer
        assertSame(pointer, empty.append(pointer));
    }

    /**
     * Test append with regular pointers (not derived from tail)
     */
    @Test
    public void testAppendRegularPointers() {
        JsonPointer ptr1 = JsonPointer.compile("/a1");
        JsonPointer ptr2 = JsonPointer.compile("/b/c");

        JsonPointer result = ptr1.append(ptr2);

        assertEquals("/a1/b/c", result.toString());
        assertEquals(JsonPointer.compile("/a1/b/c"), result);
    }

    /**
     * Test append with multi-level tail
     */
    @Test
    public void testAppendMultiLevelTail() {
        // Original: /x/y/z/w
        JsonPointer original = JsonPointer.compile("/x/y/z/w");

        // Get tail: should be /y/z/w
        JsonPointer tail = original.tail();
        assertEquals("/y/z/w", tail.toString());

        // Get tail of tail: should be /z/w
        JsonPointer tailOfTail = tail.tail();
        assertEquals("/z/w", tailOfTail.toString());

        // Append tailOfTail to another pointer
        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer result = base.append(tailOfTail);

        assertEquals("/a/z/w", result.toString());
    }

    /**
     * Test append with single segment tail
     */
    @Test
    public void testAppendSingleSegmentTail() {
        // Original: /a/b
        JsonPointer original = JsonPointer.compile("/a/b");

        // Get tail: should be /b
        JsonPointer tail = original.tail();
        assertEquals("/b", tail.toString());

        // Append to another pointer
        JsonPointer base = JsonPointer.compile("/x");
        JsonPointer result = base.append(tail);

        assertEquals("/x/b", result.toString());
    }

    /**
     * Test that append no longer incorrectly strips trailing slashes
     * (This was part of the legacy logic that was removed in the fix)
     */
    @Test
    public void testAppendPreservesPointerStructure() {
        JsonPointer ptr1 = JsonPointer.compile("/a");
        JsonPointer ptr2 = JsonPointer.compile("/b");

        JsonPointer result = ptr1.append(ptr2);

        // Should be /a/b, not /ab or any other variation
        assertEquals("/a/b", result.toString());

        // Verify structure is correct
        assertFalse(result.toString().endsWith("//"));
    }

    /**
     * Test append with array index in tail
     */
    @Test
    public void testAppendTailWithArrayIndex() {
        // Original: /items/0/name
        JsonPointer original = JsonPointer.compile("/items/0/name");

        // Get tail: should be /0/name
        JsonPointer tail = original.tail();
        assertEquals("/0/name", tail.toString());

        // Append to another pointer
        JsonPointer base = JsonPointer.compile("/data");
        JsonPointer result = base.append(tail);

        assertEquals("/data/0/name", result.toString());
    }

    /**
     * Test append with escaped property names in tail
     */
    @Test
    public void testAppendTailWithEscapedProperty() {
        // Original: /a~1b/c (where ~1 represents /)
        JsonPointer original = JsonPointer.compile("/a~1b/c");

        // Get tail: should be /c
        JsonPointer tail = original.tail();
        assertEquals("/c", tail.toString());

        // Append to another pointer
        JsonPointer base = JsonPointer.compile("/x");
        JsonPointer result = base.append(tail);

        assertEquals("/x/c", result.toString());
    }

    /**
     * Comprehensive test reproducing the exact scenario from issue #1168
     */
    @Test
    public void testIssue1168Reproduction() {
        // Exact scenario from the issue description
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail();  // tailPointer represents "/b/c"
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tailPointer);

        // Should be "/a2/b/c", NOT "/a2/a1/b/c"
        assertEquals("/a2/b/c", concatenated.toString());

        // Verify it matches the expected compiled pointer
        JsonPointer expected = JsonPointer.compile("/a2/b/c");
        assertEquals("Concatenated pointer should match expected pointer", expected, concatenated);

        // Additional verification: ensure the segments are correct
        assertEquals("a2", concatenated.getMatchingProperty());

        JsonPointer nextSegment = concatenated.tail();
        assertNotNull("Should have remaining segments", nextSegment);
        assertEquals("/b/c", nextSegment.toString());
    }
}

