package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for JsonPointer.append() method to verify fix for issue #1168.
 * 
 * Issue: JsonPointer.append(JsonPointer.tail()) was incorrectly including
 * segments from the original pointer because it used _asString directly
 * instead of toString() which properly handles _asStringOffset.
 */
public class JsonPointerAppendTest {

    @Test
    public void testAppendWithTailPointer() {
        // Create original pointer: /a1/b/c
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail pointer: /b/c (but internally shares _asString with offset)
        JsonPointer tailPointer = original.tail();

        // Create another pointer: /a2
        JsonPointer other = JsonPointer.compile("/a2");

        // Append tail to other - should result in /a2/b/c
        JsonPointer result = other.append(tailPointer);

        // Verify the result is correct (not /a2/a1/b/c)
        assertEquals("/a2/b/c", result.toString());
    }

    @Test
    public void testAppendWithTailPointerFromSingleSegment() {
        // Create original pointer: /a1
        JsonPointer original = JsonPointer.compile("/a1");

        // Get tail pointer: should be EMPTY
        JsonPointer tailPointer = original.tail();

        // Create another pointer: /a2
        JsonPointer other = JsonPointer.compile("/a2");

        // Append tail to other - should result in /a2 (tail is empty)
        JsonPointer result = other.append(tailPointer);

        // Verify the result
        assertEquals("/a2", result.toString());
    }

    @Test
    public void testAppendWithTailPointerFromDeepPath() {
        // Create original pointer: /a/b/c/d/e
        JsonPointer original = JsonPointer.compile("/a/b/c/d/e");

        // Get tail pointer: /c/d/e
        JsonPointer tailPointer = original.tail().tail();

        // Create another pointer: /x
        JsonPointer other = JsonPointer.compile("/x");

        // Append tail to other - should result in /x/c/d/e
        JsonPointer result = other.append(tailPointer);

        // Verify the result
        assertEquals("/x/c/d/e", result.toString());
    }

    @Test
    public void testAppendWithEmptyPointer() {
        // Create empty pointer
        JsonPointer empty = JsonPointer.empty();

        // Create another pointer: /a2
        JsonPointer other = JsonPointer.compile("/a2");

        // Append empty to other - should result in /a2
        JsonPointer result = other.append(empty);

        // Verify the result
        assertEquals("/a2", result.toString());

        // Append other to empty - should result in /a2
        JsonPointer result2 = empty.append(other);
        assertEquals("/a2", result2.toString());
    }

    @Test
    public void testAppendWithTailPointerAndIndex() {
        // Create original pointer with index: /a1/0/c
        JsonPointer original = JsonPointer.compile("/a1/0/c");

        // Get tail pointer: /0/c
        JsonPointer tailPointer = original.tail();

        // Create another pointer: /a2
        JsonPointer other = JsonPointer.compile("/a2");

        // Append tail to other - should result in /a2/0/c
        JsonPointer result = other.append(tailPointer);

        // Verify the result
        assertEquals("/a2/0/c", result.toString());
    }

    @Test
    public void testAppendPropertyAfterTail() {
        // Create original pointer: /a1/b/c
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail pointer: /b/c
        JsonPointer tailPointer = original.tail();

        // Create another pointer and append property
        JsonPointer other = JsonPointer.compile("/a2");

        // Append property to other
        JsonPointer withProperty = other.appendProperty("prop");

        // Verify the result
        assertEquals("/a2/prop", withProperty.toString());
    }

    @Test
    public void testAppendIndexAfterTail() {
        // Create original pointer: /a1/b/c
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail pointer: /b/c
        JsonPointer tailPointer = original.tail();

        // Create another pointer and append index
        JsonPointer other = JsonPointer.compile("/a2");

        // Append index to other
        JsonPointer withIndex = other.appendIndex(5);

        // Verify the result
        assertEquals("/a2/5", withIndex.toString());
    }

    @Test
    public void testTailPointerToStringCorrectness() {
        // Verify that tail() returns correct toString() representation
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail();

        // tail() should return /b/c
        assertEquals("/b/c", tailPointer.toString());

        // Verify the tail pointer can be used in append correctly
        JsonPointer base = JsonPointer.compile("/x");
        JsonPointer result = base.append(tailPointer);
        assertEquals("/x/b/c", result.toString());
    }

    @Test
    public void testMultipleTailOperations() {
        // Create original pointer: /a/b/c/d
        JsonPointer original = JsonPointer.compile("/a/b/c/d");

        // Get tail after multiple operations: /c/d
        JsonPointer tailPointer = original.tail().tail();

        // Create another pointer: /x
        JsonPointer other = JsonPointer.compile("/x");

        // Append tail to other - should result in /x/c/d
        JsonPointer result = other.append(tailPointer);

        // Verify the result
        assertEquals("/x/c/d", result.toString());
    }

    @Test
    public void testAppendDoesNotModifyOriginal() {
        // Create original pointer: /a1/b/c
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        String originalToString = original.toString();

        // Get tail pointer
        JsonPointer tailPointer = original.tail();

        // Create another pointer
        JsonPointer other = JsonPointer.compile("/a2");

        // Append tail to other
        JsonPointer result = other.append(tailPointer);

        // Verify original pointer is unchanged
        assertEquals(originalToString, original.toString());
        assertEquals("/a2/b/c", result.toString());
    }
}

