        // When appending a tail pointer, it should not include segments from the original pointer
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail();  // Should represent "/b/c"
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tailPointer);

