package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.StringReader;

import static org.junit.Assert.*;

/**
 * Unit tests for Base64 padding read behavior fix.
 * Verifies that Base64Variant configured with PADDING_ALLOWED does not throw
 * MissingPadding exception when padding characters are missing.
 */
public class Base64PaddingReadTest {

    /**
     * Test UTF8StreamJsonParser (InputStream) with PADDING_ALLOWED and missing padding.
     * Covers _decodeBase64 method fix.
     */
    @Test
    public void testBase64MissingPaddingAllowedInputStream() throws Exception {
        // Base64 for "Ma" is "TWE=". Without padding: "TWE" (3 chars).
        // This triggers the check after 3rd char in _decodeBase64/_readBinary.
        String json = "{\"data\":\"TWE\"}";
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        JsonFactory factory = new JsonFactory();
        InputStream in = new ByteArrayInputStream(json.getBytes("UTF-8"));
        try (JsonParser parser = factory.createParser(in)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            parser.nextToken(); // VALUE_STRING

            // This triggers _decodeBase64 in UTF8StreamJsonParser
            byte[] binary = parser.getBinaryValue(variant);

            assertNotNull(binary);
            assertEquals(2, binary.length);
            assertEquals('M', (char) binary[0]);
            assertEquals('a', (char) binary[1]);
        }
    }

    /**
     * Test UTF8StreamJsonParser (InputStream) with PADDING_ALLOWED and missing padding using readBinaryValue.
     * Covers _readBinary method fix.
     */
    @Test
    public void testBase64MissingPaddingAllowedInputStreamReadBinary() throws Exception {
        String json = "{\"data\":\"TWE\"}";
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        JsonFactory factory = new JsonFactory();
        InputStream in = new ByteArrayInputStream(json.getBytes("UTF-8"));
        try (JsonParser parser = factory.createParser(in)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            parser.nextToken(); // VALUE_STRING

            ByteArrayOutputStream out = new ByteArrayOutputStream();
            // This triggers _readBinary in UTF8StreamJsonParser
            int count = parser.readBinaryValue(variant, out);

            assertEquals(2, count);
            byte[] binary = out.toByteArray();
            assertEquals('M', (char) binary[0]);
            assertEquals('a', (char) binary[1]);
        }
    }

    /**
     * Test with 2 Base64 chars (1 byte output), missing two '=' padding chars.
     * Base64 for "M" is "TQ==". Without padding: "TQ".
     * This triggers the check after 2nd char (which is treated as 3rd position logic in loop) 
     * where quote is found immediately.
     */
    @Test
    public void testBase64MissingPaddingAllowedTwoChars() throws Exception {
        String json = "{\"data\":\"TQ\"}";
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        JsonFactory factory = new JsonFactory();
        InputStream in = new ByteArrayInputStream(json.getBytes("UTF-8"));
        try (JsonParser parser = factory.createParser(in)) {
            parser.nextToken(); 
            parser.nextToken(); 
            parser.nextToken(); 

            byte[] binary = parser.getBinaryValue(variant);

            assertNotNull(binary);
            assertEquals(1, binary.length);
            assertEquals('M', (char) binary[0]);
        }
    }

    /**
     * Test ReaderBasedJsonParser (Reader) with PADDING_ALLOWED and missing padding.
     * Ensures the fix applies to ReaderBasedJsonParser as well.
     */
    @Test
    public void testBase64MissingPaddingAllowedReader() throws Exception {
        String json = "{\"data\":\"TWE\"}";
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(new StringReader(json))) {
            parser.nextToken(); 
            parser.nextToken(); 
            parser.nextToken(); 

            byte[] binary = parser.getBinaryValue(variant);

            assertNotNull(binary);
            assertEquals(2, binary.length);
            assertEquals('M', (char) binary[0]);
            assertEquals('a', (char) binary[1]);
        }
    }

    /**
     * Ensure that PADDING_REQUIRED still fails when padding is missing.
     * This verifies that the fix does not break the strict padding requirement.
     */
    @Test
    public void testBase64MissingPaddingRequiredShouldFail() throws Exception {
        String json = "{\"data\":\"TWE\"}";
