package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

import java.io.StringWriter;
import java.io.IOException;

public class FilteringGeneratorDelegateTest {

    @Test
    public void testWriteStartObjectCreatesContextWhenFilterIsNull() throws IOException {
        StringWriter sw = new StringWriter();
        JsonGenerator delegate = new JsonFactory().createGenerator(sw);

        // Filter that includes first array element, but excludes second (returns null)
        // This simulates the scenario where checkValue returns null
        TokenFilter filter = new TokenFilter() {
            @Override
            public TokenFilter includeElement(int index) {
                if (index == 0) {
                    return INCLUDE_ALL;
                }
                return null; // This triggers the bug path where f == null
            }
        };

        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(delegate, filter, false, false);

        // Start Array
        gen.writeStartArray();
        assertEquals(true, gen._filterContext.inArray());

        // Start Object 1 (Included)
        gen.writeStartObject();
        assertEquals(true, gen._filterContext.inObject());

        // End Object 1
        gen.writeEndObject();
        assertEquals(true, gen._filterContext.inArray());

        // Start Object 2 (Excluded - filter returns null)
        // Before patch: _filterContext would remain TYPE_ARRAY
        // After patch: _filterContext should become TYPE_OBJECT (child context created)
        gen.writeStartObject();

        // CRITICAL ASSERTION: Verifies the fix ensures context is created even when filter is null
        assertEquals(true, gen._filterContext.inObject());

        // End Object 2
        gen.writeEndObject();
        assertEquals(true, gen._filterContext.inArray());

        // End Array
        gen.writeEndArray();

        gen.close();
    }

    @Test
    public void testWriteStartObjectWithArgsCreatesContextWhenFilterIsNull() throws IOException {
        StringWriter sw = new StringWriter();
        JsonGenerator delegate = new JsonFactory().createGenerator(sw);

        TokenFilter filter = new TokenFilter() {
            @Override
            public TokenFilter includeElement(int index) {
                if (index == 0) {
                    return INCLUDE_ALL;
                }
                return null; 
            }
        };

        FilteringGeneratorDelegate gen = new FilteringGeneratorDelegate(delegate, filter, false, false);

        gen.writeStartArray();
        assertEquals(true, gen._filterContext.inArray());

        // Use writeStartObject(Object, int) - The focal method from context
        gen.writeStartObject(this, 10);
        assertEquals(true, gen._filterContext.inObject());

        gen.writeEndObject();
        assertEquals(true, gen._filterContext.inArray());

        // Excluded object using the overloaded method
        gen.writeStartObject(this, 10);

        // Assert context is created even if filtered out (Patch verification)
        assertEquals(true, gen._filterContext.inObject());

        gen.writeEndObject();
        assertEquals(true, gen._filterContext.inArray());

        gen.writeEndArray();
        gen.close();
    }
}

