public class TextBufferEmptyTest {

    @Test
    public void testGetTextBufferReturnsEmptyArrayWhenEmpty() {
        BufferRecycler recycler = new BufferRecycler();
        TextBuffer buffer = new TextBuffer(recycler);

        // Reset buffer to empty state
        buffer.resetWithEmpty();

        // Verify getTextBuffer() returns empty array, not null
        // This is the specific case fixed by the patch: 
        // Before fix: returns null because _currentSegment is null and !_hasSegments is true
        // After fix: returns NO_CHARS (empty array) because it falls through to contentsAsArray()
        char[] textBuffer = buffer.getTextBuffer();
        Assert.assertNotNull("getTextBuffer() should not return null for empty buffer", textBuffer);
        Assert.assertEquals("getTextBuffer() should return array of length 0 for empty buffer", 0, textBuffer.length);

        // Call contentsAsString()
        String content = buffer.contentsAsString();
        Assert.assertEquals("contentsAsString() should return empty string", "", content);

        // Verify getTextBuffer() continues to return empty array
        char[] textBufferAfter = buffer.getTextBuffer();
        Assert.assertNotNull("getTextBuffer() should not return null after contentsAsString()", textBufferAfter);
        Assert.assertEquals("getTextBuffer() should return array of length 0 after contentsAsString()", 0, textBufferAfter.length);
    }
}

