package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonParseException;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

/**
 * Test class for verifying Base64 padding behavior in JSON parsers.
 * This test validates the fix for the issue where Base64Variant configured with
 * PADDING_ALLOWED still threw MissingPadding exception when encountering
 * Base64 strings missing optional '=' padding characters.
 */
public class ReaderBasedJsonParserBase64PaddingTest {

    /**
     * Test that Base64 data without padding is accepted when PADDING_ALLOWED is configured.
     * This verifies the fix where requiresPaddingOnRead() is used instead of usesPadding().
     */
    @Test
    public void testBase64MissingPaddingWithPaddingAllowed() throws IOException {
        // Create a Base64Variant with PADDING_ALLOWED read behavior
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Base64 string without padding (SGVsbG8 = "Hello" without the trailing =)
        String base64WithoutPadding = "SGVsbG8";
        String json = "{\"data\": \"" + base64WithoutPadding + "\"}";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            // Navigate through the JSON structure
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME ("data")
            parser.nextToken(); // VALUE_STRING (the Base64 value)

            // This should NOT throw MissingPadding exception after the fix
            byte[] decoded = parser.getBinaryValue(variant);

            // Verify the decoded data is correct
            String result = new String(decoded, "UTF-8");
            assertEquals("Hello", result);
        }
    }

    /**
     * Test that Base64 data without padding throws exception when PADDING_REQUIRED is configured.
     * This verifies that the fix doesn't break the expected behavior for PADDING_REQUIRED.
     */
    @Test
    public void testBase64MissingPaddingWithPaddingRequired() throws IOException {
        // Create a Base64Variant with PADDING_REQUIRED (default behavior)
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS;

        // Base64 string without padding
        String base64WithoutPadding = "SGVsbG8";
        String json = "{\"data\": \"" + base64WithoutPadding + "\"}";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            // Navigate through the JSON structure
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME ("data")
            parser.nextToken(); // VALUE_STRING (the Base64 value)

            // This SHOULD throw an exception for missing padding
            try {
                parser.getBinaryValue(variant);
                fail("Expected JsonParseException for missing padding with PADDING_REQUIRED");
            } catch (JsonParseException e) {
                // Expected - verify the exception message mentions padding
                assertTrue("Exception should mention padding", 
                    e.getMessage().toLowerCase().contains("padding"));
            }
        }
    }

    /**
     * Test that Base64 data with proper padding works correctly with PADDING_ALLOWED.
     */
    @Test
    public void testBase64WithPaddingAndPaddingAllowed() throws IOException {
        // Create a Base64Variant with PADDING_ALLOWED read behavior
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Base64 string WITH padding
        String base64WithPadding = "SGVsbG8=";
        String json = "{\"data\": \"" + base64WithPadding + "\"}";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            // Navigate through the JSON structure
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME ("data")
            parser.nextToken(); // VALUE_STRING (the Base64 value)

            // This should work fine
            byte[] decoded = parser.getBinaryValue(variant);

            // Verify the decoded data is correct
            String result = new String(decoded, "UTF-8");
            assertEquals("Hello", result);
        }
    }

    /**
     * Test Base64 data with 2 characters missing padding (produces 1 byte).
     * This tests the code path where decodedData >>= 4 is executed.
     */
    @Test
    public void testBase64TwoCharsMissingPadding() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // "H" = 0x48 = Base64 "SA==" (with padding) or "SA" (without)
        String base64WithoutPadding = "SA";
        String json = "{\"data\": \"" + base64WithoutPadding + "\"}";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            parser.nextToken(); // VALUE_STRING

            byte[] decoded = parser.getBinaryValue(variant);

            assertEquals(1, decoded.length);
            assertEquals((byte) 'H', decoded[0]);
        }
    }

    /**
     * Test Base64 data with 3 characters missing padding (produces 2 bytes).
     * This tests the code path where decodedData >>= 2 is executed.
     */
    @Test
    public void testBase64ThreeCharsMissingPadding() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // "He" = 0x48 0x65 = Base64 "SGU=" (with padding) or "SGU" (without)
