            assertEquals((byte) 'e', decoded[1]);
        }
    }

    /**
     * Test that PADDING_ALLOWED also allows missing padding with different input sizes.
     * Note: PADDING_INDEPENDENT is not available in this version, using PADDING_ALLOWED instead.
     */
    @Test
    public void testBase64MissingPaddingWithPaddingAllowedVariant() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

