import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonParseException;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

/**
 * Test for Base64 padding read behavior fix.
 * Verifies that Base64Variant.requiresPaddingOnRead() is used instead of usesPadding()
 * when determining whether to throw MissingPadding exception.
 * 
 * This test covers the patch that changes b64variant.usesPadding() to 
 * b64variant.requiresPaddingOnRead() in ReaderBasedJsonParser, UTF8DataInputJsonParser,
 * and UTF8StreamJsonParser _readBinary and _decodeBase64 methods.
 */
public class Base64PaddingReadBehaviorTest {

    @Test
    public void testBase64OneByteWithoutPaddingWhenPaddingAllowed() throws IOException {
        // Test case for 2 Base64 chars at end -> 1 byte remaining
        // "Hello" = 5 bytes = "SGVsbG8=" with padding, "SGVsbG8" without
        // The last 2 chars "G8" decode to 1 byte "o"
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        String base64WithoutPadding = "SGVsbG8";
        String json = "{\"data\": \"" + base64WithoutPadding + "\"}";
        byte[] jsonBytes = json.getBytes("UTF-8");

        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser(jsonBytes)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            parser.nextToken(); // VALUE_STRING

            // This should NOT throw MissingPadding exception with PADDING_ALLOWED
            // Before the fix, this would fail because usesPadding() returned true
            // even when PADDING_ALLOWED was set
            byte[] decoded = parser.getBinaryValue(variant);

            String decodedString = new String(decoded, "UTF-8");
            assertEquals("Hello", decodedString);
        }
    }

    @Test
    public void testBase64TwoBytesWithoutPaddingWhenPaddingAllowed() throws IOException {
        // Test case for 3 Base64 chars at end -> 2 bytes remaining
        // "Hi" = 2 bytes = "SGk=" with padding, "SGk" without
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        String base64WithoutPadding = "SGk";
        String json = "{\"data\": \"" + base64WithoutPadding + "\"}";
        byte[] jsonBytes = json.getBytes("UTF-8");

        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser(jsonBytes)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            parser.nextToken(); // VALUE_STRING

            // This should NOT throw MissingPadding exception with PADDING_ALLOWED
            // Tests the code path where 3 Base64 chars remain before closing quote
            byte[] decoded = parser.getBinaryValue(variant);

            String decodedString = new String(decoded, "UTF-8");
            assertEquals("Hi", decodedString);
        }
    }

    @Test
    public void testBase64WithoutPaddingWhenPaddingRequired() throws IOException {
        // Verify that PADDING_REQUIRED still throws exception for missing padding
        // This ensures we didn't break existing behavior
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_REQUIRED);

        String base64WithoutPadding = "SGVsbG8";
        String json = "{\"data\": \"" + base64WithoutPadding + "\"}";
        byte[] jsonBytes = json.getBytes("UTF-8");

        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser(jsonBytes)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            parser.nextToken(); // VALUE_STRING

            try {
                parser.getBinaryValue(variant);
                fail("Expected JsonParseException for missing padding when PADDING_REQUIRED");
            } catch (JsonParseException e) {
                // Expected - verify the exception message mentions padding
                assertTrue("Exception should mention padding", 
                    e.getMessage().toLowerCase().contains("padding"));
            }
        }
    }

    @Test
    public void testBase64WithoutPaddingWhenPaddingAllowedAlternative() throws IOException {
        // Test PADDING_ALLOWED behavior - should also allow missing padding
        // Note: PADDING_INDEPENDENT may not exist in all versions, using PADDING_ALLOWED instead
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

