        try (JsonParser parser = factory.createParser(jsonBytes)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            parser.nextToken(); // VALUE_STRING

            // This should NOT throw exception with PADDING_ALLOWED
            byte[] decoded = parser.getBinaryValue(variant);

            String decodedString = new String(decoded, "UTF-8");
            assertEquals("Hello", decodedString);
        }
    }

    @Test
    public void testBase64WithPaddingStillWorks() throws IOException {
        // Verify that Base64 with proper padding still works correctly
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
            Base64Variant.PaddingReadBehaviour.PADDING_REQUIRED);

        String base64WithPadding = "SGVsbG8=";
        String json = "{\"data\": \"" + base64WithPadding + "\"}";
        byte[] jsonBytes = json.getBytes("UTF-8");

        JsonFactory factory = new JsonFactory();

        try (JsonParser parser = factory.createParser(jsonBytes)) {
            parser.nextToken(); // START_OBJECT
            parser.nextToken(); // FIELD_NAME
            parser.nextToken(); // VALUE_STRING

            // This should work fine with proper padding
            byte[] decoded = parser.getBinaryValue(variant);

            String decodedString = new String(decoded, "UTF-8");
            assertEquals("Hello", decodedString);
        }
    }
}

