package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.filter.TokenFilter.Inclusion;
import org.junit.Test;
import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.assertEquals;

public class FilteringGeneratorDelegateTest {

    @Test
    public void testWriteStartObjectWithNullFilterMaintainsContext() throws IOException {
        JsonFactory factory = new JsonFactory();
        StringWriter sw = new StringWriter();
        JsonGenerator delegate = factory.createGenerator(sw);

        // Filter that returns null for the second element (index 1) in an array.
        // This triggers the 'f == null' branch in writeStartObject.
        TokenFilter filter = new TokenFilter() {
            @Override
            public TokenFilter includeElement(int index) {
                if (index == 1) {
                    return null; // Filter out this element completely
                }
                return TokenFilter.INCLUDE_ALL;
            }
        };

        // Create FilteringGeneratorDelegate
        // Using Inclusion.INCLUDE_ALL_AND_PATH to ensure filter logic is tested
        // Constructor signature: (JsonGenerator, TokenFilter, Inclusion, boolean)
        FilteringGeneratorDelegate generator = new FilteringGeneratorDelegate(
            delegate, filter, Inclusion.INCLUDE_ALL_AND_PATH, false);

        generator.writeStartArray(); 

        // Element 0: Included (index 0)
        generator.writeStartObject(); 
        generator.writeFieldName("id");
        generator.writeNumber(1);
        generator.writeEndObject();

        // Element 1: Filtered out (index 1)
        // includeElement returns null, so checkValue returns null.
        // The patch ensures createChildObjectContext is called even when filter is null.
        // Without the patch, _filterContext is not updated, causing context mismatch on writeEndObject/writeFieldName.
        generator.writeStartObject(); 
        generator.writeFieldName("id");
        generator.writeNumber(2);
        generator.writeEndObject();   

        generator.writeEndArray();
        generator.close();

        // Verification
        // Expected output should only contain the first object: [{"id":1}]
        // If the bug exists, writeEndObject for Element 1 might corrupt the context stack
        // causing writeEndArray to fail or output to be malformed.
        String output = sw.toString();
        assertEquals("[{\"id\":1}]", output);
    }
}

