package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

import java.io.*;
import java.nio.ByteBuffer;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.json.async.NonBlockingByteBufferJsonParser;

public class JsonFactoryCanonicalizeFieldNamesTest {

    @Test
    public void testNonBlockingByteBufferParserRespectsCanonicalizeFieldNames() throws Exception {
        // Test with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = new JsonFactory();
        factory.disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        JsonParser parser = factory.createNonBlockingByteBufferParser();

        // Verify the parser's symbol table is not canonicalizing
        ByteQuadsCanonicalizer symbols = getParserSymbols(parser);
        assertFalse("Symbol table should not be canonicalizing when feature is disabled", 
                    symbols.isCanonicalizing());

        // Verify parsing works and triggers _addName logic in NonBlockingJsonParserBase
        verifyNonBlockingByteBufferParsing((NonBlockingByteBufferJsonParser) parser);

        // Test with CANONICALIZE_FIELD_NAMES enabled (default)
        factory = new JsonFactory();
        factory.enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        parser = factory.createNonBlockingByteBufferParser();

        symbols = getParserSymbols(parser);
        assertTrue("Symbol table should be canonicalizing when feature is enabled", 
                   symbols.isCanonicalizing());

        // Verify parsing works with canonicalization enabled
        verifyNonBlockingByteBufferParsing((NonBlockingByteBufferJsonParser) parser);
    }

    @Test
    public void testNonBlockingByteArrayParserRespectsCanonicalizeFieldNames() throws Exception {
        // Test with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = new JsonFactory();
        factory.disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        JsonParser parser = factory.createNonBlockingByteArrayParser();

        // Verify the parser's symbol table is not canonicalizing
        ByteQuadsCanonicalizer symbols = getParserSymbols(parser);
        assertFalse("Symbol table should not be canonicalizing when feature is disabled", 
                    symbols.isCanonicalizing());

        parser.close();

        // Test with CANONICALIZE_FIELD_NAMES enabled (default)
        factory = new JsonFactory();
        factory.enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        parser = factory.createNonBlockingByteArrayParser();

        symbols = getParserSymbols(parser);
        assertTrue("Symbol table should be canonicalizing when feature is enabled", 
                   symbols.isCanonicalizing());

        parser.close();
    }

    @Test
    public void testDataInputParserRespectsCanonicalizeFieldNames() throws Exception {
        // Test with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = new JsonFactory();
        factory.disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        ByteArrayInputStream bais = new ByteArrayInputStream("{\"field\":\"value\"}".getBytes("UTF-8"));
        DataInput dataInput = new DataInputStream(bais);

        JsonParser parser = factory.createParser(dataInput);

        // Verify the parser's symbol table is not canonicalizing
        ByteQuadsCanonicalizer symbols = getParserSymbols(parser);
        assertFalse("Symbol table should not be canonicalizing when feature is disabled", 
                    symbols.isCanonicalizing());

        // Verify parsing works and triggers addName logic in UTF8DataInputJsonParser
        verifyDataInputParsing(parser);

        // Test with CANONICALIZE_FIELD_NAMES enabled (default)
        factory = new JsonFactory();
        factory.enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        bais = new ByteArrayInputStream("{\"field\":\"value\"}".getBytes("UTF-8"));
        dataInput = new DataInputStream(bais);

        parser = factory.createParser(dataInput);

        symbols = getParserSymbols(parser);
        assertTrue("Symbol table should be canonicalizing when feature is enabled", 
                   symbols.isCanonicalizing());

        // Verify parsing works with canonicalization enabled
        verifyDataInputParsing(parser);
    }

    @Test
    public void testParsingWorksCorrectlyWithCanonicalizeFieldNamesDisabled() throws Exception {
        // Test that parsing still works correctly when canonicalization is disabled
        JsonFactory factory = new JsonFactory();
        factory.disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES);

        NonBlockingByteBufferJsonParser parser = (NonBlockingByteBufferJsonParser) factory.createNonBlockingByteBufferParser();

        byte[] jsonBytes = "{\"name\":\"test\",\"value\":123}".getBytes("UTF-8");
        ByteBuffer buffer = ByteBuffer.wrap(jsonBytes);

        parser.feedInput(buffer);
        parser.endOfInput();

        // Parse the JSON and verify field names are returned correctly
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("name", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("test", parser.getText());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("value", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(123, parser.getIntValue());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());

        parser.close();
    }

    private void verifyNonBlockingByteBufferParsing(NonBlockingByteBufferJsonParser parser) throws Exception {
        byte[] jsonBytes = "{\"f\":\"v\"}".getBytes("UTF-8");
        ByteBuffer buffer = ByteBuffer.wrap(jsonBytes);
        parser.feedInput(buffer);
        parser.endOfInput();

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("f", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("v", parser.getText());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        parser.close();
    }

    private void verifyDataInputParsing(JsonParser parser) throws Exception {
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("field", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value", parser.getText());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        parser.close();
    }

    private ByteQuadsCanonicalizer getParserSymbols(JsonParser parser) throws Exception {
        // Use reflection to access the _symbols field in the parser, searching superclasses.
        // This fixes the NoSuchFieldException encountered when _symbols is defined in a superclass
        // (e.g., NonBlockingJsonParserBase) rather than the concrete parser class.
        Class<?> clazz = parser.getClass();
        while (clazz != null) {
            try {
                java.lang.reflect.Field symbolsField = clazz.getDeclaredField("_symbols");
                symbolsField.setAccessible(true);
                return (ByteQuadsCanonicalizer) symbolsField.get(parser);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException("_symbols not found in class hierarchy of " + parser.getClass());
    }
}

