    private ByteQuadsCanonicalizer getParserSymbols(JsonParser parser) throws Exception {
        // Use reflection to access the _symbols field in the parser, searching superclasses.
        // This fixes the NoSuchFieldException encountered when _symbols is defined in a superclass
