import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

import static org.junit.Assert.*;

/**
 * Test for Base64 padding read behavior fix.
 * 
 * This test verifies that when a Base64Variant is configured with PADDING_ALLOWED
 * read behavior, the parser correctly accepts Base64-encoded data without padding
 * characters. The fix changes the parser to use requiresPaddingOnRead() instead
 * of the deprecated usesPadding() method.
 * 
 * Optimizations:
 * 1. Fixed incorrect Base64 data in testReadBase64TwoCharsWithoutPadding ("SQ" -> "SA")
 *    to correctly decode to 'H' (72) instead of 'I' (73).
 * 2. Added test case for UTF8StreamJsonParser to ensure patch coverage across parser implementations.
 * 3. Ensured both PADDING_ALLOWED and PADDING_REQUIRED paths are tested for 2-char and 3-char inputs.
 */
public class Base64PaddingReadBehaviourTest {

    @Test
    public void testReadBase64WithoutPaddingWhenPaddingAllowed() throws IOException {
        // Base64Variant with PADDING_ALLOWED should accept missing padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
            .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // "SGk" is "Hi" in Base64 without padding (normally "SGk=")
        // This is 3 Base64 characters which decodes to 2 bytes
        String base64WithoutPadding = "SGk";
        String json = "\"" + base64WithoutPadding + "\"";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            parser.nextToken(); // VALUE_STRING

            // This should NOT throw an exception with PADDING_ALLOWED
            byte[] decoded = parser.getBinaryValue(variant);

            // Verify the decoded data is correct
            assertEquals(2, decoded.length);
            assertEquals('H', (char) decoded[0]);
            assertEquals('i', (char) decoded[1]);
        }
    }

    @Test
    public void testReadBase64WithoutPaddingWhenPaddingRequired() throws IOException {
        // Base64Variant with PADDING_REQUIRED should reject missing padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
            .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_REQUIRED);

        // "SGk" is "Hi" in Base64 without padding (normally "SGk=")
        String base64WithoutPadding = "SGk";
        String json = "\"" + base64WithoutPadding + "\"";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            parser.nextToken(); // VALUE_STRING

            // This SHOULD throw an exception with PADDING_REQUIRED
            try {
                byte[] decoded = parser.getBinaryValue(variant);
                fail("Expected exception for missing padding");
            } catch (IOException e) {
                // Expected - should mention padding or Base64
                String msg = e.getMessage().toLowerCase();
                assertTrue("Exception should mention padding or Base64", 
                    msg.contains("padding") || msg.contains("base64"));
            }
        }
    }

    @Test
    public void testReadBase64WithPaddingWhenPaddingAllowed() throws IOException {
        // Base64Variant with PADDING_ALLOWED should also accept proper padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
            .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // "SGk=" is "Hi" in Base64 with padding
        String base64WithPadding = "SGk=";
        String json = "\"" + base64WithPadding + "\"";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            parser.nextToken(); // VALUE_STRING

            // This should work fine
            byte[] decoded = parser.getBinaryValue(variant);

            // Verify the decoded data is correct
            assertEquals(2, decoded.length);
            assertEquals('H', (char) decoded[0]);
            assertEquals('i', (char) decoded[1]);
        }
    }

    @Test
    public void testReadBase64TwoCharsWithoutPadding() throws IOException {
        // Test with 2 Base64 characters (decodes to 1 byte)
        // "SA" is "H" in Base64 without padding (normally "SA==")
        // Fixed from "SQ" which decodes to 'I' (73), not 'H' (72)
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
            .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        String base64WithoutPadding = "SA";
        String json = "\"" + base64WithoutPadding + "\"";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            parser.nextToken(); // VALUE_STRING

            // This should NOT throw an exception with PADDING_ALLOWED
            byte[] decoded = parser.getBinaryValue(variant);

            // Verify the decoded data is correct (1 byte for "H")
            assertEquals(1, decoded.length);
            assertEquals('H', (char) decoded[0]);
        }
    }

    @Test
    public void testReadBase64TwoCharsWithoutPaddingWhenPaddingRequired() throws IOException {
        // Test with 2 Base64 characters when padding is required
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
            .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_REQUIRED);

        // Using "SA" for consistency, though any 2-char string would trigger the exception
        String base64WithoutPadding = "SA";
        String json = "\"" + base64WithoutPadding + "\"";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            parser.nextToken(); // VALUE_STRING

            // This SHOULD throw an exception with PADDING_REQUIRED
            try {
                byte[] decoded = parser.getBinaryValue(variant);
                fail("Expected exception for missing padding");
            } catch (IOException e) {
                // Expected - should mention padding or Base64
                String msg = e.getMessage().toLowerCase();
                assertTrue("Exception should mention padding or Base64", 
                    msg.contains("padding") || msg.contains("base64"));
            }
        }
    }

    @Test
    public void testReadBase64FourCharsWithoutPadding() throws IOException {
        // Test with 4 Base64 characters (complete triplet, no padding needed)
        // "SGVs" decodes to "Hel" (3 bytes, complete triplet)
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
            .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        String base64Complete = "SGVs";
        String json = "\"" + base64Complete + "\"";

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(json)) {
            parser.nextToken(); // VALUE_STRING

            // This should work fine (complete triplet)
            byte[] decoded = parser.getBinaryValue(variant);

            // Verify the decoded data is correct
            assertEquals(3, decoded.length);
            assertEquals("Hel", new String(decoded, "UTF-8"));
        }
    }

    /**
     * Additional test to cover UTF8StreamJsonParser code path.
     * The patch modifies ReaderBasedJsonParser, UTF8StreamJsonParser, and UTF8DataInputJsonParser.
     * Using an InputStream forces JsonFactory to create UTF8StreamJsonParser.
     */
    @Test
    public void testReadBase64TwoCharsWithoutPaddingInputStream() throws IOException {
        // Test with 2 Base64 characters using InputStream (UTF8StreamJsonParser)
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
            .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        String base64WithoutPadding = "SA";
        String json = "\"" + base64WithoutPadding + "\"";
        InputStream inputStream = new ByteArrayInputStream(json.getBytes("UTF-8"));

        JsonFactory factory = new JsonFactory();
        try (JsonParser parser = factory.createParser(inputStream)) {
            parser.nextToken(); // VALUE_STRING

            // This should NOT throw an exception with PADDING_ALLOWED
            byte[] decoded = parser.getBinaryValue(variant);

            // Verify the decoded data is correct (1 byte for "H")
            assertEquals(1, decoded.length);
            assertEquals('H', (char) decoded[0]);
        }
    }
}

