package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.json.UTF8DataInputJsonParser;
import com.fasterxml.jackson.core.json.async.NonBlockingJsonParser;
import com.fasterxml.jackson.core.json.async.NonBlockingByteBufferJsonParser;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;

import static org.junit.Assert.*;

/**
 * Test class to verify that JsonFactory respects CANONICALIZE_FIELD_NAMES feature
 * for non-blocking and DataInput parsers (Issue #1015).
 * 
 * Optimized to fix reflection issues and ensure coverage of patch changes.
 */
public class JsonFactoryCanonicalizeFieldNamesTest {

    /**
     * Test that createNonBlockingByteArrayParser respects CANONICALIZE_FIELD_NAMES disabled.
     * Covers: JsonFactory.createNonBlockingByteArrayParser
     */
    @Test
    public void testNonBlockingByteArrayParserRespectsCanonicalizeFieldNamesDisabled() throws IOException {
        // Create factory with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = new JsonFactory();
        factory = factory.rebuild()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Create non-blocking byte array parser
        JsonParser parser = factory.createNonBlockingByteArrayParser();

        // Verify parser is NonBlockingJsonParser
        assertTrue("Parser should be NonBlockingJsonParser", parser instanceof NonBlockingJsonParser);

        // Verify the canonicalizer is not canonicalizing
        ByteQuadsCanonicalizer canonicalizer = getParserSymbols(parser);
        assertNotNull("Canonicalizer should not be null", canonicalizer);
        assertFalse("Canonicalizer should not be canonicalizing when CANONICALIZE_FIELD_NAMES is disabled",
                canonicalizer.isCanonicalizing());

        parser.close();
    }

    /**
     * Test that createNonBlockingByteBufferParser respects CANONICALIZE_FIELD_NAMES disabled.
     * Covers: JsonFactory.createNonBlockingByteBufferParser
     */
    @Test
    public void testNonBlockingByteBufferParserRespectsCanonicalizeFieldNamesDisabled() throws IOException {
        // Create factory with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = new JsonFactory();
        factory = factory.rebuild()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Create non-blocking byte buffer parser
        JsonParser parser = factory.createNonBlockingByteBufferParser();

        // Verify parser is NonBlockingByteBufferJsonParser
        assertTrue("Parser should be NonBlockingByteBufferJsonParser", parser instanceof NonBlockingByteBufferJsonParser);

        // Verify the canonicalizer is not canonicalizing
        ByteQuadsCanonicalizer canonicalizer = getParserSymbols(parser);
        assertNotNull("Canonicalizer should not be null", canonicalizer);
        assertFalse("Canonicalizer should not be canonicalizing when CANONICALIZE_FIELD_NAMES is disabled",
                canonicalizer.isCanonicalizing());

        parser.close();
    }

    /**
     * Test that createParser(DataInput) respects CANONICALIZE_FIELD_NAMES disabled.
     * Covers: JsonFactory._createParser(DataInput, IOContext)
     */
    @Test
    public void testDataInputParserRespectsCanonicalizeFieldNamesDisabled() throws IOException {
        // Create factory with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = new JsonFactory();
        factory = factory.rebuild()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Create a simple DataInput from byte array
        byte[] jsonData = "{\"field\":\"value\"}".getBytes("UTF-8");
        ByteArrayInputStream bais = new ByteArrayInputStream(jsonData);
        DataInput dataInput = new DataInputStream(bais);

        // Create parser from DataInput
        JsonParser parser = factory.createParser(dataInput);

        // Verify parser is UTF8DataInputJsonParser
        assertTrue("Parser should be UTF8DataInputJsonParser", parser instanceof UTF8DataInputJsonParser);

        // Verify the canonicalizer is not canonicalizing
        ByteQuadsCanonicalizer canonicalizer = getParserSymbols(parser);
        assertNotNull("Canonicalizer should not be null", canonicalizer);
        assertFalse("Canonicalizer should not be canonicalizing when CANONICALIZE_FIELD_NAMES is disabled",
                canonicalizer.isCanonicalizing());

        parser.close();
    }

    /**
     * Test that field names are processed correctly when CANONICALIZE_FIELD_NAMES is disabled.
     * This verifies the logic in NonBlockingJsonParserBase._addName method.
     */
    @Test
    public void testFieldNamesProcessingWhenCanonicalizeDisabled() throws IOException {
        // Create factory with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = new JsonFactory();
        factory = factory.rebuild()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Create non-blocking byte array parser
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();

        // Feed JSON data with field name
        String json = "{\"name\":\"value\"}";
        byte[] jsonData = json.getBytes("UTF-8");

        parser.feedInput(jsonData, 0, jsonData.length);

        // Parse to trigger field name processing
        JsonToken token = parser.nextToken();
        assertEquals("First token should be START_OBJECT", JsonToken.START_OBJECT, token);

        token = parser.nextToken();
        assertEquals("Second token should be FIELD_NAME", JsonToken.FIELD_NAME, token);
        assertEquals("Field name should be 'name'", "name", parser.getCurrentName());

        // Verify canonicalizer state
        ByteQuadsCanonicalizer canonicalizer = getParserSymbols(parser);
        assertNotNull("Canonicalizer should not be null", canonicalizer);
        assertFalse("Canonicalizer should not be canonicalizing", canonicalizer.isCanonicalizing());

        parser.close();
    }

    /**
     * Test that field names ARE canonicalized when CANONICALIZE_FIELD_NAMES is enabled (default).
     */
    @Test
    public void testFieldNamesCanonicalizedWhenEnabled() throws IOException {
        // Create factory with CANONICALIZE_FIELD_NAMES enabled (default)
        JsonFactory factory = new JsonFactory();
        factory = factory.rebuild()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Create non-blocking byte array parser
        JsonParser parser = factory.createNonBlockingByteArrayParser();

        // Verify the canonicalizer IS canonicalizing
        ByteQuadsCanonicalizer canonicalizer = getParserSymbols(parser);
        assertNotNull("Canonicalizer should not be null", canonicalizer);
        assertTrue("Canonicalizer should be canonicalizing when CANONICALIZE_FIELD_NAMES is enabled",
                canonicalizer.isCanonicalizing());

        parser.close();
    }

    /**
     * Helper method to extract the _symbols field from parser using reflection.
     * Searches the class hierarchy to find the field, fixing NoSuchFieldException 
     * when the field is declared in a superclass (e.g. NonBlockingJsonParserBase).
     */
    private ByteQuadsCanonicalizer getParserSymbols(JsonParser parser) throws IOException {
        Class<?> clazz = parser.getClass();
        while (clazz != null) {
            try {
                Field symbolsField = clazz.getDeclaredField("_symbols");
                symbolsField.setAccessible(true);
                return (ByteQuadsCanonicalizer) symbolsField.get(parser);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            } catch (IllegalAccessException e) {
                throw new IOException("Failed to access _symbols field", e);
            }
        }
        throw new IOException("Failed to find _symbols field in class hierarchy for " + parser.getClass());
    }
}

