/**
 * Unit tests for JsonPointer.append() method and related functionality.
 * Optimized to:
 * 1. Fix assertion failure in testAppendWithEmptyPointer (corrected logic).
 * 2. Ensure coverage of toString() usage in append() (the core fix for #1168).
 * 3. Ensure coverage of equals() with offset logic (Uncovered Lines context).
 * 4. Validate removal of legacy trailing slash logic in appendIndex.
 * 5. Cover the new toStringBuilder() helper method.
 */
public class JsonPointerAppendTest {

    @Test
    public void testAppendWithTailPointer() {
        // Issue #1168: Original pointer: /a1/b/c
        JsonPointer original = JsonPointer.compile("/a1/b/c");

        // Get tail: /b/c (shares _asString with original but has offset)
        JsonPointer tailPointer = original.tail();

        // Another pointer: /a2
        JsonPointer other = JsonPointer.compile("/a2");

        // Append tail to other: should be /a2/b/c, NOT /a2/a1/b/c
        // This verifies that append() uses toString() instead of _asString
        JsonPointer concatenated = other.append(tailPointer);

        // Verify the result is correct
        assertEquals("/a2/b/c", concatenated.toString());
        assertEquals(JsonPointer.compile("/a2/b/c"), concatenated);
    }

    @Test
    public void testAppendWithTailPointerDeepNesting() {
        // Test with deeper nesting to ensure offset handling works correctly
        JsonPointer original = JsonPointer.compile("/x/y/z/w");
        JsonPointer tail = original.tail(); // Should be /y/z/w
        JsonPointer tail2 = tail.tail(); // Should be /z/w

        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer result = base.append(tail2);

        assertEquals("/a/z/w", result.toString());
        assertEquals(JsonPointer.compile("/a/z/w"), result);
    }

    @Test
    public void testAppendWithEmptyPointer() {
        JsonPointer empty = JsonPointer.empty();
        JsonPointer pointer = JsonPointer.compile("/a/b");

        // Appending empty to pointer should return equivalent pointer
        assertEquals(pointer, pointer.append(empty));
        assertEquals(pointer.toString(), pointer.append(empty).toString());

        // Appending pointer to empty should return equivalent pointer
        // Fixed assertion: was incorrectly expecting 'empty' instead of 'pointer'
        assertEquals(pointer, empty.append(pointer));
        assertEquals(pointer.toString(), empty.append(pointer).toString());
    }

    @Test
    public void testAppendProperty() {
        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer withProperty = base.appendProperty("b");

        assertEquals("/a/b", withProperty.toString());
        assertEquals(JsonPointer.compile("/a/b"), withProperty);
    }

    @Test
    public void testAppendPropertyWithSpecialChars() {
        // Test that appendProperty properly escapes special characters
        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer withProperty = base.appendProperty("b~c");

        assertEquals("/a/b~0c", withProperty.toString());
    }

    @Test
    public void testAppendIndex() {
        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer withIndex = base.appendIndex(0);

        assertEquals("/a/0", withIndex.toString());
        assertEquals(JsonPointer.compile("/a/0"), withIndex);
    }

    @Test
    public void testAppendIndexNoTrailingSlashRemoval() {
        // Verify that appendIndex no longer incorrectly removes trailing slashes
        // This validates the removal of legacy logic in the patch
        JsonPointer base = JsonPointer.compile("/a/");
        JsonPointer withIndex = base.appendIndex(0);

        // Should be /a//0 (the trailing slash is part of the path)
        // Old logic would have produced /a/0
        assertEquals("/a//0", withIndex.toString());
    }

    @Test
    public void testTailPointerEquality() {
        // Verify that tail pointers are equal to compiled equivalents
        // This exercises the equals() method with offset logic (Uncovered Lines context)
        // Specifically targets the _compare logic in equals()
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail();
        JsonPointer compiled = JsonPointer.compile("/b/c");

        // This calls equals() which compares _asString with offsets
        assertEquals(compiled, tail);
        assertEquals(compiled.toString(), tail.toString());
    }

    @Test
    public void testAppendChainWithTail() {
        // Test chaining multiple append operations with tail pointers
        JsonPointer p1 = JsonPointer.compile("/a/b/c");
        JsonPointer p2 = JsonPointer.compile("/d");

        JsonPointer tail = p1.tail(); // /b/c
        JsonPointer result = p2.append(tail); // /d/b/c

        assertEquals("/d/b/c", result.toString());

        // Further append
        JsonPointer tail2 = result.tail(); // /b/c
        JsonPointer p3 = JsonPointer.compile("/e");
        JsonPointer finalResult = p3.append(tail2);

        assertEquals("/e/b/c", finalResult.toString());
    }

    @Test
    public void testAppendWithRootTail() {
        // Test appending tail from root pointer
        JsonPointer root = JsonPointer.compile("/");
        JsonPointer tail = root.tail(); // Should be empty

        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer result = base.append(tail);

        assertEquals("/a", result.toString());
    }

    @Test
    public void testToStringBuilder() {
        // Test the new toStringBuilder method added in 2.17
        JsonPointer original = JsonPointer.compile("/a/b/c");
        JsonPointer tail = original.tail();

        StringBuilder sb = tail.toStringBuilder(0);
        assertEquals("/b/c", sb.toString());

        StringBuilder sb2 = tail.toStringBuilder(10);
        assertEquals("/b/c", sb2.toString());
    }
}

