package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.*;

/**
 * Unit tests for the includeEmptyArray/includeEmptyObject feature.
 * Tests verify that custom TokenFilter implementations can control
 * whether empty arrays and objects are preserved after filtering.
 */
public class TokenFilterEmptyStructuresTest {

    /**
     * Test TokenFilter that includes empty objects
     */
    static class IncludeEmptyObjectFilter extends TokenFilter {
        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            return true;
        }

        @Override
        public TokenFilter includeProperty(String name) {
            // Filter out all properties to create empty object
            return null;
        }
    }

    /**
     * Test TokenFilter that includes empty arrays
     */
    static class IncludeEmptyArrayFilter extends TokenFilter {
        @Override
        public boolean includeEmptyArray(boolean contentsFiltered) {
            return true;
        }

        @Override
        public TokenFilter includeElement(int index) {
            // Filter out all elements to create empty array
            return null;
        }
    }

    /**
     * Test TokenFilter that excludes empty objects (default behavior)
     */
    static class ExcludeEmptyObjectFilter extends TokenFilter {
        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            return false;
        }

        @Override
        public TokenFilter includeProperty(String name) {
            return null;
        }
    }

    /**
     * Test TokenFilter that excludes empty arrays (default behavior)
     */
    static class ExcludeEmptyArrayFilter extends TokenFilter {
        @Override
        public boolean includeEmptyArray(boolean contentsFiltered) {
            return false;
        }

        @Override
        public TokenFilter includeElement(int index) {
            return null;
        }
    }

    /**
     * Test TokenFilter that tracks filterFinishObject calls
     */
    static class TrackingObjectFilter extends TokenFilter {
        final boolean includeEmpty;
        boolean finishCalled = false;

        public TrackingObjectFilter(boolean includeEmpty) {
            this.includeEmpty = includeEmpty;
        }

        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            return includeEmpty;
        }

        @Override
        public void filterFinishObject() {
            finishCalled = true;
        }

        @Override
        public TokenFilter includeProperty(String name) {
            return null;
        }
    }

    /**
     * Test TokenFilter that tracks filterFinishArray calls
     */
    static class TrackingArrayFilter extends TokenFilter {
        final boolean includeEmpty;
        boolean finishCalled = false;

        public TrackingArrayFilter(boolean includeEmpty) {
            this.includeEmpty = includeEmpty;
        }

        @Override
        public boolean includeEmptyArray(boolean contentsFiltered) {
            return includeEmpty;
        }

        @Override
        public void filterFinishArray() {
            finishCalled = true;
        }

        @Override
        public TokenFilter includeElement(int index) {
            return null;
        }
    }

    @Test
    public void testCloseObjectWithIncludeEmptyObject() throws IOException {
        // Test TokenFilterContext.closeObject() with filter that includes empty objects
        TokenFilter filter = new IncludeEmptyObjectFilter();
        TokenFilterContext rootContext = TokenFilterContext.createRootContext(filter);
        TokenFilterContext objectContext = rootContext.createChildObjectContext(filter, false);

        StringWriter writer = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator gen = factory.createGenerator(writer);

        // Simulate closing an empty object (start not handled)
        objectContext.closeObject(gen);
        gen.close();

        String output = writer.toString();
        // Should write empty object {}
        assertEquals("{}", output);
    }

    @Test
    public void testCloseObjectWithExcludeEmptyObject() throws IOException {
        // Test TokenFilterContext.closeObject() with filter that excludes empty objects
        TokenFilter filter = new ExcludeEmptyObjectFilter();
        TokenFilterContext rootContext = TokenFilterContext.createRootContext(filter);
        TokenFilterContext objectContext = rootContext.createChildObjectContext(filter, false);

        StringWriter writer = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator gen = factory.createGenerator(writer);

        // Simulate closing an empty object (start not handled)
        objectContext.closeObject(gen);
        gen.close();

        String output = writer.toString();
        // Should write nothing (empty object excluded)
        assertEquals("", output);
    }

    @Test
    public void testCloseArrayWithIncludeEmptyArray() throws IOException {
        // Test TokenFilterContext.closeArray() with filter that includes empty arrays
        TokenFilter filter = new IncludeEmptyArrayFilter();
        TokenFilterContext rootContext = TokenFilterContext.createRootContext(filter);
        TokenFilterContext arrayContext = rootContext.createChildArrayContext(filter, false);

        StringWriter writer = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator gen = factory.createGenerator(writer);

        // Simulate closing an empty array (start not handled)
        arrayContext.closeArray(gen);
        gen.close();

        String output = writer.toString();
        // Should write empty array []
        assertEquals("[]", output);
    }

    @Test
    public void testCloseArrayWithExcludeEmptyArray() throws IOException {
        // Test TokenFilterContext.closeArray() with filter that excludes empty arrays
        TokenFilter filter = new ExcludeEmptyArrayFilter();
        TokenFilterContext rootContext = TokenFilterContext.createRootContext(filter);
        TokenFilterContext arrayContext = rootContext.createChildArrayContext(filter, false);

        StringWriter writer = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator gen = factory.createGenerator(writer);

        // Simulate closing an empty array (start not handled)
        arrayContext.closeArray(gen);
        gen.close();

        String output = writer.toString();
        // Should write nothing (empty array excluded)
        assertEquals("", output);
    }

    @Test
    public void testCloseObjectWithStartHandled() throws IOException {
        // Test that when start is already handled, closeObject writes end object only
        TokenFilter filter = new IncludeEmptyObjectFilter();
        TokenFilterContext rootContext = TokenFilterContext.createRootContext(filter);
        // Create context with startHandled=true (context assumes start was written)
        TokenFilterContext objectContext = rootContext.createChildObjectContext(filter, true);

        StringWriter writer = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator gen = factory.createGenerator(writer);

        // When startHandled is true, we MUST write the start object first
        // The context assumes start was already written, so we write it manually
        gen.writeStartObject();

        // Now close the object - should write end object only
        objectContext.closeObject(gen);
        gen.close();

        String output = writer.toString();
        // Should write complete object {}
        assertEquals("{}", output);
    }

    @Test
    public void testCloseArrayWithStartHandled() throws IOException {
        // Test that when start is already handled, closeArray writes end array only
        TokenFilter filter = new IncludeEmptyArrayFilter();
        TokenFilterContext rootContext = TokenFilterContext.createRootContext(filter);
        // Create context with startHandled=true
        TokenFilterContext arrayContext = rootContext.createChildArrayContext(filter, true);

        StringWriter writer = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator gen = factory.createGenerator(writer);

        // When startHandled is true, we MUST write the start array first
        gen.writeStartArray();

        // Now close the array
        arrayContext.closeArray(gen);
        gen.close();

        String output = writer.toString();
        // Should write complete array []
        assertEquals("[]", output);
    }

    @Test
    public void testFilteringParserWithIncludeEmptyObject() throws IOException {
        // Test FilteringParserDelegate with filter that includes empty objects
        JsonFactory factory = new JsonFactory();
        String input = "{\"name\":\"value\",\"filtered\":\"data\"}";

        TokenFilter filter = new IncludeEmptyObjectFilter();
        JsonParser parser = factory.createParser(input);
        FilteringParserDelegate filteringParser = new FilteringParserDelegate(
            parser, filter, true, false);

        StringWriter writer = new StringWriter();
        JsonGenerator gen = factory.createGenerator(writer);

        // Copy tokens through filtering parser
        while (filteringParser.nextToken() != null) {
            gen.copyCurrentEvent(filteringParser);
        }
        gen.close();
        parser.close();

        String output = writer.toString();
        // Should include empty object since all properties were filtered
        assertTrue("Output should contain empty object: " + output, output.contains("{}"));
    }

    @Test
    public void testFilteringParserWithIncludeEmptyArray() throws IOException {
        // Test FilteringParserDelegate with filter that includes empty arrays
        JsonFactory factory = new JsonFactory();
        String input = "[1,2,3]";

        TokenFilter filter = new IncludeEmptyArrayFilter();
        JsonParser parser = factory.createParser(input);
        FilteringParserDelegate filteringParser = new FilteringParserDelegate(
            parser, filter, true, false);

        StringWriter writer = new StringWriter();
        JsonGenerator gen = factory.createGenerator(writer);

        // Copy tokens through filtering parser
        while (filteringParser.nextToken() != null) {
            gen.copyCurrentEvent(filteringParser);
        }
        gen.close();
        parser.close();

        String output = writer.toString();
        // Should include empty array since all elements were filtered
        assertTrue("Output should contain empty array: " + output, output.contains("[]"));
    }

    @Test
    public void testFilteringParserWithExcludeEmptyObject() throws IOException {
        // Test FilteringParserDelegate with filter that excludes empty objects (default)
        JsonFactory factory = new JsonFactory();
        String input = "{\"name\":\"value\"}";

        TokenFilter filter = new ExcludeEmptyObjectFilter();
        JsonParser parser = factory.createParser(input);
        FilteringParserDelegate filteringParser = new FilteringParserDelegate(
            parser, filter, true, false);

        StringWriter writer = new StringWriter();
        JsonGenerator gen = factory.createGenerator(writer);

        // Copy tokens through filtering parser
        while (filteringParser.nextToken() != null) {
            gen.copyCurrentEvent(filteringParser);
        }
        gen.close();
        parser.close();

        String output = writer.toString();
        // Should NOT include empty object
        assertFalse("Output should not contain empty object: " + output, output.contains("{}"));
    }

    @Test
    public void testFilteringParserWithExcludeEmptyArray() throws IOException {
        // Test FilteringParserDelegate with filter that excludes empty arrays (default)
        JsonFactory factory = new JsonFactory();
        String input = "[1,2,3]";

        TokenFilter filter = new ExcludeEmptyArrayFilter();
        JsonParser parser = factory.createParser(input);
        FilteringParserDelegate filteringParser = new FilteringParserDelegate(
            parser, filter, true, false);

        StringWriter writer = new StringWriter();
        JsonGenerator gen = factory.createGenerator(writer);

        // Copy tokens through filtering parser
        while (filteringParser.nextToken() != null) {
            gen.copyCurrentEvent(filteringParser);
        }
        gen.close();
        parser.close();

        String output = writer.toString();
        // Should NOT include empty array
        assertFalse("Output should not contain empty array: " + output, output.contains("[]"));
        assertEquals("", output);
    }

    @Test
    public void testIncludeEmptyObjectMethodDefault() {
        // Verify default implementation returns false
        TokenFilter defaultFilter = new TokenFilter() {};
        assertFalse("Default includeEmptyObject should return false",
            defaultFilter.includeEmptyObject(false));
        assertFalse("Default includeEmptyObject should return false",
            defaultFilter.includeEmptyObject(true));
    }

    @Test
    public void testIncludeEmptyArrayMethodDefault() {
        // Verify default implementation returns false
        TokenFilter defaultFilter = new TokenFilter() {};
        assertFalse("Default includeEmptyArray should return false",
            defaultFilter.includeEmptyArray(false));
        assertFalse("Default includeEmptyArray should return false",
            defaultFilter.includeEmptyArray(true));
    }

    @Test
    public void testContentsFilteredParameter() {
        // Test that contentsFiltered parameter is passed correctly
        final boolean[] capturedValues = new boolean[2];
        final int[] callCount = new int[1];

        TokenFilter filter = new TokenFilter() {
            @Override
            public boolean includeEmptyObject(boolean contentsFiltered) {
                if (callCount[0] < 2) {
                    capturedValues[callCount[0]++] = contentsFiltered;
                }
                return true;
            }
        };

        // The parameter should distinguish between originally empty vs filtered-empty
        assertTrue(filter.includeEmptyObject(false));
        assertTrue(filter.includeEmptyObject(true));
        assertEquals(2, callCount[0]);
    }

    @Test
    public void testNestedEmptyStructures() throws IOException {
        // Test nested empty structures with include filter
        JsonFactory factory = new JsonFactory();
        String input = "{\"outer\":{\"inner\":\"value\"}}";

        TokenFilter filter = new TokenFilter() {
            @Override
            public boolean includeEmptyObject(boolean contentsFiltered) {
