package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.*;

/**
 * Unit tests for the includeEmptyArray/includeEmptyObject feature.
 * Tests verify that custom TokenFilter implementations can control
 * whether empty arrays and objects are preserved after filtering.
 */
public class TokenFilterEmptyStructuresTest {

    /**
     * Test TokenFilter that includes empty objects
     */
    static class IncludeEmptyObjectFilter extends TokenFilter {
        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            return true;
        }

        @Override
        public TokenFilter includeProperty(String name) {
            // Filter out all properties to create empty object
            return null;
        }
    }

    /**
     * Test TokenFilter that includes empty arrays
     */
    static class IncludeEmptyArrayFilter extends TokenFilter {
        @Override
        public boolean includeEmptyArray(boolean contentsFiltered) {
            return true;
        }

        @Override
        public TokenFilter includeElement(int index) {
            // Filter out all elements to create empty array
            return null;
        }
    }

    /**
     * Test TokenFilter that excludes empty objects (default behavior)
     */
    static class ExcludeEmptyObjectFilter extends TokenFilter {
        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            return false;
        }

        @Override
        public TokenFilter includeProperty(String name) {
            return null;
        }
    }

    /**
     * Test TokenFilter that excludes empty arrays (default behavior)
     */
    static class ExcludeEmptyArrayFilter extends TokenFilter {
